import pyaudio
import numpy as np
import time
import os

# Konfiguracja
CHUNK = 1024
FORMAT = pyaudio.paInt16
CHANNELS = 2  # Stereo (lewy/prawy kanał do detekcji kierunku)
RATE = 44100

def clear_screen():
    os.system('cls' if os.name == 'nt' else 'clear')

def get_audio_stream():
    p = pyaudio.PyAudio()
    stream = p.open(format=FORMAT,
                    channels=CHANNELS,
                    rate=RATE,
                    input=True,
                    frames_per_buffer=CHUNK)
    return p, stream

def analyze_direction(data):
    """
    Analizuje dane audio i określa kierunek na podstawie głośności lewego/prawego kanału.
    """
    # Rozdziel dane na kanały L i R
    left_channel = data[::2]   # Co druga próbka to lewy kanał
    right_channel = data[1::2] # Co druga próbka to prawy kanał

    # Oblicz RMS (głośność) dla każdego kanału
    rms_left = np.sqrt(np.mean(left_channel.astype(np.float32)**2))
    rms_right = np.sqrt(np.mean(right_channel.astype(np.float32)**2))

    total_volume = rms_left + rms_right

    # Jeśli cisza - nic nie rób
    if total_volume < 500: # Próg czułości (dostosuj!)
        return None

    # Określ kierunek
    diff = rms_left - rms_right

    if abs(diff) < 100:
        return "CENTRUM"
    elif diff > 0:
        return "LEWO"
    else:
        return "PRAWO"

def main():
    print("Uruchamianie pomocnika dla niesłyszących...")
    print("Naciśnij Ctrl+C aby zatrzymać.")

    p, stream = get_audio_stream()

    try:
        while True:
            # Czytaj dane z bufora
            data = stream.read(CHUNK, exception_on_overflow=False)

            # Zamień bajty na tablicę numpy
            data_int = np.frombuffer(data, dtype=np.int16)

            # Analizuj kierunek
            direction = analyze_direction(data_int)

            clear_screen()
            print("="*30)
            print("🔊 WSKAŹNIK KIERUNKU DŹWIĘKU 🔊")
            print("="*30)

            if direction:
                if direction == "LEWO":
                    print("👈 LEWO 👈")
                elif direction == "PRAWO":
                    print("👉 PRAWO 👉")
                elif direction == "CENTRUM":
                    print("⬆️ CENTRUM ⬆️")
            else:
                print("😶 Cicho...")

            print("="*30)
            time.sleep(0.1) # Odświeżanie co 100ms

    except KeyboardInterrupt:
        print("\nZatrzymywanie...")
    finally:
        stream.stop_stream()
        stream.close()
        p.terminate()

if __name__ == "__main__":
    main()
